def secondLargest(arr: list[int]) -> int:
    if len(arr) < 2:
        return 0
    num1 = arr[0]
    num2 = arr[1]
    if num1 < num2:
        num1, num2 = num2, num1
    for i in range(2, len(arr)):
        v = arr[i]
        if v > num1:
            num2 = num1
            num1 = v
        elif v < num1 and v > num2:
            num2 = v
    return num2

def main() -> None:
    test_cases = [
        [1, 2, 3, 4, 5],
        [5, 4, 3, 2, 1],
        [1, 1, 2, 2, 3, 3],
        [10, 20, 20, 30, 30, 30],
        [-5, -4, -3, -2, -1],
        [100],
        [],
        [7, 7, 7, 7],
        [0, 0, 1, 1],
        [42, 42, 42, 43],
    ]
    for arr in test_cases:
        result = secondLargest(arr)
        print(result)

if __name__ == "__main__":
    main()

