#include <limits.h>

typedef struct {
    long long* data;
    size_t len;
} Arr_i64;

Arr_i64 arr_new_i64(size_t len) {
    Arr_i64 a;
    a.data = (long long*)malloc(len * sizeof(long long));
    a.len = len;
    return a;
}

void arr_free_i64(Arr_i64 a) {
    free(a.data);
}

long long secondLargest(Arr_i64 arr) {
    long long num1 = LLONG_MIN;
