        long long val = arr.data[i];
        if (val > num1) {
            num2 = num1;
            num1 = val;
        } else if (val > num2 && val != num1) {
            num2 = val;
        }
    }

    if (num2 == LLONG_MIN) {
        for (size_t i = 0; i < arr.len; i++) {
            long long val = arr.data[i];
            if (val < num1 && val > num2) {
