import java.util.*;

public class Solution {
    public static long secondLargest(long[] arr) {
        if (arr.length < 2) {
            return Long.MIN_VALUE;
        }

        long num1 = Long.MIN_VALUE;
        long num2 = Long.MIN_VALUE;

        for (long value : arr) {
            if (value > num1) {
                num2 = num1;
                num1 = value;
            } else if (value > num2 && value < num1) {
                num2 = value;
            }
        }

        return num2;
    }

    public static void main(String[] args) {
        List<long[]> testCases = new ArrayList<>();
        testCases.add(new long[]{5, 2, 8, 1, 9, 3});
        testCases.add(new long[]{10, 10, 9, 8, 7, 6});
        testCases.add(new long[]{-5, -2, -8, -1, -9});
        testCases.add(new long[]{0, 1, 0, 1, 0, 2});
        testCases.add(new long[]{Long.MAX_VALUE, Long.MAX_VALUE - 1, Long.MAX_VALUE - 2});
        testCases.add(new long[]{1});
        testCases.add(new long[]{});
        testCases.add(new long[]{5, 5, 5, 5});

        for (long[] testCase : testCases) {
            long result = secondLargest(testCase);
            System.out.println(Arrays.toString(testCase) + " -> " + result);
        }
    }
}
